'use strict';
const device=document.querySelector('#device'),rotate=document.querySelector('#rotate'),frame=document.querySelector('#website'),phone=document.querySelector('#phone'),stage=document.querySelector('#stage'),space=document.querySelector('#scaled-space'),fit=document.querySelector('#fit');
let landscape=false;
function sizePreview(){let [width,height]=device.value.split(',').map(Number);if(landscape)[width,height]=[height,width];const outerWidth=width+20,outerHeight=height+52;frame.style.width=width+'px';frame.style.height=height+'px';phone.style.width=outerWidth+'px';phone.style.height=outerHeight+'px';const css=getComputedStyle(stage);const availableWidth=stage.clientWidth-parseFloat(css.paddingLeft)-parseFloat(css.paddingRight);const availableHeight=stage.clientHeight-parseFloat(css.paddingTop)-parseFloat(css.paddingBottom);const scale=fit.checked?Math.max(.1,Math.min(1,availableWidth/outerWidth,availableHeight/outerHeight)):1;phone.style.transform=`scale(${scale})`;space.style.width=outerWidth*scale+'px';space.style.height=outerHeight*scale+'px';stage.style.justifyContent=outerWidth*scale>availableWidth?'flex-start':'center';document.querySelector('#dimensions').textContent=`${width} × ${height}`;document.querySelector('#scale').textContent=`${Math.round(scale*100)}%`;rotate.textContent=landscape?'切换为竖屏 ↻':'切换为横屏 ↻';rotate.setAttribute('aria-pressed',String(landscape))}
device.addEventListener('change',sizePreview);fit.addEventListener('change',sizePreview);rotate.addEventListener('click',()=>{landscape=!landscape;sizePreview()});document.querySelector('#reload').addEventListener('click',()=>{frame.src='./index.html'});new ResizeObserver(sizePreview).observe(stage);sizePreview();
